public class ExtraTextDetector extends ResourceXmlDetector {
    private static final Implementation IMPLEMENTATION = new Implementation(ExtraTextDetector.class, Scope.RESOURCE_FILE_SCOPE);
    public static final Issue ISSUE = Issue.create("ExtraText", ...);
    @Override
    public boolean appliesTo(ResourceFolderType... folderTypes) {
        for (ResourceFolderType folderType : folderTypes) {
            if (folderType != ResourceFolderType.VALUES) return true;
        }
        return false;
    }
    @Override
    public Collection<String> getApplicableElements() { return ALL; }
    @Override
    public void visitElement(XmlContext context, Element element) {
        NodeList children = element.getChildNodes();
        for (int i=0; i<children.getLength(); i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.TEXT_NODE || child.getNodeType() == Node.CDATA_SECTION_NODE) {
                String text = child.getNodeValue();
                if (!text.trim().isEmpty()) {
                    context.report(ISSUE, child, context.getLocation(child), "Unexpected text found in resource file");
                }
            }
        }
    }
}
```
